package cn.zhuatech.contentai.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class GroundingQualityService{public Result evaluate(Request r){double coverage=r.sourcedClaims()*100.0/r.factualClaims();int score=(int)Math.round(Math.min(100,coverage*.7+Math.min(20,r.trustedSources()*4)+(r.generatedContentDisclosed()?10:0)-r.contradictions()*20));score=Math.max(0,score);List<String> gaps=new ArrayList<>();if(coverage<90)gaps.add("补充未引用事实主张的可靠来源");if(r.contradictions()>0)gaps.add("解决来源之间的事实冲突");if(!r.generatedContentDisclosed())gaps.add("标注 AI 生成或辅助内容");String status=(r.highRiskTopic()&&score<80)||r.contradictions()>1?"BLOCK":score<80?"REVIEW":"PUBLISH";if(gaps.isEmpty())gaps.add("事实依据和披露满足发布条件");return new Result(Math.round(coverage*10)/10.0,score,status,gaps);}
 public record Request(@Min(1) int factualClaims,@Min(0) int sourcedClaims,@Min(0) int trustedSources,@Min(0) int contradictions,@NotNull Boolean generatedContentDisclosed,@NotNull Boolean highRiskTopic){}public record Result(double sourceCoverage,int groundingScore,String status,List<String> gaps){} }
